 97	/**
 98	 * Display abbreviations for pipeline stage type strings.
 99	 *
100	 * Maps each ledger pipeline type to the two- or three-character label shown

101	 * in the pipeline-track badge column of the project-detail table.
102	 * `buildPipelineTrack` falls back to `stage.type.slice(0, 3).toUpperCase()`
103	 * for any type that is absent from this map, so unknown types render
104	 * gracefully but without a meaningful abbreviation.
105	 *
106	 * **Maintenance contract:** whenever a new pipeline type is added to the
107	 * ledger (e.g., in `PIPELINE_TYPES` on the server), add a corresponding
108	 * entry here.  Omitting a new type will not cause a runtime error, but the
109	 * badge label in the GUI will be a raw three-character slice of the type
110	 * string instead of a human-readable abbreviation.
111	 */
112	var STAGE_ABBREV = {
113	  'implementation':     'DEV',
114	  'qa':                 'QA',
115	  'security-audit':     'SEC',
116	  'code-review':        'REV',
117	  'release-engineering':'REL',
118	  'documentation':      'DOC'
119	};
120	
121	function buildPipelineTrack(overviewEntry) {
122	  if (!overviewEntry || !overviewEntry.pipeline_stages || !overviewEntry.pipeline_stages.length) {
123	    return '—';
124	  }
125	  var badges = overviewEntry.pipeline_stages.map(function (stage) {
126	    var abbrev = STAGE_ABBREV[stage.type] || stage.type.slice(0, 3).toUpperCase();
127	    var statusClass = 'stage-pending';
128	    if (stage.status === 'in-progress') statusClass = 'stage-in-progress';
129	    else if (stage.status === 'pass')        statusClass = 'stage-pass';
130	    else if (stage.status === 'fail')        statusClass = 'stage-fail';
131	    var tooltip = escapeHtml(stage.type) + ' — ' + escapeHtml(stage.agent);
132	    if (stage.rework_count > 0) tooltip += ' (rework: ' + stage.rework_count + ')';
133	    var reworkBadge = stage.rework_count > 0
134	      ? '<span class="rework-indicator" title="Rework count: ' + stage.rework_count + '">' + stage.rework_count + '</span>'
135	      : '';
136	    return '<span class="stage-badge ' + statusClass + '" title="' + tooltip + '">' +
137	      escapeHtml(abbrev) +
138	      reworkBadge +
139	    '</span>';
140	  }).join('');
141	  return '<div class="pipeline-track">' + badges + '</div>';
142	}
143	
144	function buildRunBadges(item, isActive) {
145	  var badges = '';
146	  if (isActive) {
147	    badges += '<span class="badge badge-in-progress">Running</span>';
148	  }
149	  if (item && item.is_dry_run) {
150	    badges += '<span class="badge badge-dry-run">Dry Run</span>';
151	  }
152	  return badges;
153	}
