155	/* ----------------------------------------------------------
156	   Orchestrator Toolbar
157	   Renders Kill + Resume buttons into toolbarEl.
158	   Always visible; buttons are disabled (with explanatory
159	   tooltips) when the corresponding action is unavailable.
160	
161	   opts: {
162	     loading:        bool,           — show "Loading…" disabled state
163	     hasActiveRun:   bool,           — is there an active run?
164	     queueEntry:     object|null,    — matching queue entry (kill)
165	     runMeta:        object|null,    — run metadata (resume)
166	     meta:           object,         — project meta (plan_path, status)
167	     repo:           string,
168	     slug:           string,
169	     app:            Element,        — root element (re-render after resume)
170	     onKillDone:     Function,       — called after a successful kill
171	     pollController: object|null,    — owning pollController from renderProjectDetail
172	   }
173	   ---------------------------------------------------------- */
174	function renderOrchToolbar(toolbarEl, opts) {
175	  if (!toolbarEl) return;
176	  toolbarEl.innerHTML = '';
177	
178	  var loading         = !!opts.loading;
179	  var hasActiveRun    = !!opts.hasActiveRun;
180	  var queueEntry      = opts.queueEntry      || null;
181	  var runMeta         = opts.runMeta         || null;
182	  var meta            = opts.meta            || {};
183	  var repo            = opts.repo            || '';
184	  var slug            = opts.slug            || '';
185	  var app             = opts.app             || null;
186	  var onKillDone      = typeof opts.onKillDone === 'function' ? opts.onKillDone : null;
187	  var pollController  = opts.pollController  || null;
188	
189	  // ── Kill button ─────────────────────────────────────────────────────
190	  var killDisabled = true;
191	  var killTitle    = 'Loading\u2026';
192	  if (!loading) {
193	    if (!hasActiveRun) {
194	      killTitle = 'No active run to kill';
195	    } else if (!queueEntry) {
196	      killTitle = 'Run is active but not found in the queue \u2014 use: node scripts/kill-orchestrator.js --force';
197	    } else {
198	      killDisabled = false;
199	      killTitle    = '';
200	    }
201	  }
202	
203	  if (killDisabled) {
204	    var killBtn = document.createElement('button');
205	    killBtn.type = 'button';
206	    killBtn.className = 'btn btn-danger btn-sm orchestrator-kill-btn';
207	    killBtn.textContent = 'Kill';
208	    killBtn.disabled = true;
209	    if (killTitle) killBtn.title = killTitle;
210	    toolbarEl.appendChild(killBtn);
211	  } else {
212	    toolbarEl.appendChild(
213	      OrchestratorWidgets.renderKillButton(queueEntry.id, function () {
214	        if (onKillDone) onKillDone();
215	      })
216	    );
217	  }
218	
219	  // ── Resume button ────────────────────────────────────────────────────
220	  var resumeDisabled = true;
221	  var resumeTitle    = 'Loading\u2026';
222	  if (!loading) {
223	    if (hasActiveRun) {
224	      resumeTitle = 'Cannot resume while a run is active';
225	    } else if (!meta.plan_path) {
226	      resumeTitle = 'No plan path configured for this project';
227	    } else if (meta.status === 'COMPLETE') {
228	      resumeTitle = 'Project is already complete \u2014 nothing to resume';
229	    } else if (meta.status === 'ARCHIVED') {
230	      resumeTitle = 'Project is archived';
231	    } else if (!runMeta || !runMeta.thread_id) {
232	      resumeTitle = 'No interrupted run found';
233	    } else if (runMeta.dry_run === true) {
234	      resumeTitle = 'Dry runs cannot be resumed';
235	    } else if (runMeta.result === 'SUCCESS') {
236	      resumeTitle = 'Last run completed successfully \u2014 nothing to resume';
237	    } else {
238	      resumeDisabled = false;
239	      resumeTitle    = '';
240	    }
241	  }
242	
243	  var resumeBtn = document.createElement('button');
244	  resumeBtn.id   = 'orch-resume-btn';
245	  resumeBtn.type = 'button';
246	  resumeBtn.className = 'btn btn-resume btn-sm';
247	  resumeBtn.textContent = 'Resume';
248	  resumeBtn.disabled = resumeDisabled;
249	  if (resumeTitle) resumeBtn.title = resumeTitle;

251	  if (!resumeDisabled) {
252	    var threadId = runMeta.thread_id;
253	    var planPath = meta.plan_path;
254	
255	    resumeBtn.addEventListener('click', function () {
256	      resumeBtn.disabled = true;
257	      resumeBtn.textContent = 'Resuming\u2026';
258	      // Remove any stale error banner.
259	      var prevErr = document.getElementById('orch-resume-error');
260	      if (prevErr) prevErr.remove();
261	
262	      API.orchestratorStart(planPath, false, threadId).then(function (result) {
263	        if (result && result.started) {
264	          resumeBtn.textContent = 'Launching\u2026';
265	          var pollResume = function () {
266	            API.orchestratorGetQueue().then(function (queue) {
267	              var hasActiveEntry = Array.isArray(queue) && queue.some(function (entry) {
268	                return entry && (entry.effectiveStatus === 'pending' ||
269	                                 entry.effectiveStatus === 'started');
270	              });
271	              if (hasActiveEntry) {
272	                // Settle the resume poll: the run is now active, so hand back
273	                // to the combined poll (or trigger a full re-render if no
274	                // pollController is present — legacy fallback).
275	                if (pollController) {
276	                  pollController.settleResumePolling({ app: app, repo: repo, slug: slug });
277	                } else {
278	                  Router._clearPolling();
279	                  if (app) renderProjectDetail(app, repo, slug);
280	                }
281	              }
282	            }).catch(function () { /* keep polling */ });
283	          };
284	          // Switch to resume mode: clears combined interval, starts 3s resume poll.
285	          if (pollController) {
286	            pollController.startResumePolling({ pollFn: pollResume });
287	          } else {
288	            Router._setPolling(pollResume, 3000);
289	          }
290	        } else {
291	          resumeBtn.disabled = false;
292	          resumeBtn.textContent = 'Resume';
293	          var errEl = document.getElementById('orch-resume-error');
294	          if (!errEl) {
295	            errEl = document.createElement('p');
296	            errEl.id = 'orch-resume-error';
297	            errEl.className = 'error-banner';
298	            toolbarEl.insertAdjacentElement('afterend', errEl);
299	          }
300	          errEl.textContent = 'Resume could not be started.';
301	        }
302	      }).catch(function (err) {
303	        resumeBtn.disabled = false;
304	        resumeBtn.textContent = 'Resume';
305	        var errEl = document.getElementById('orch-resume-error');
306	        if (!errEl) {
307	          errEl = document.createElement('p');
308	          errEl.id = 'orch-resume-error';
309	          errEl.className = 'error-banner';
310	          toolbarEl.insertAdjacentElement('afterend', errEl);
311	        }
312	        errEl.textContent = 'Resume failed: ' + (err.message || String(err));
313	      });
314	    });
315	  }
316	
317	  toolbarEl.appendChild(resumeBtn);
318	}
