454	/* ----------------------------------------------------------
455	   4c-iii. State Snapshot & Diff Helpers
456	   Pure functions — no DOM access, JSON-serializable outputs.
457	   Used by WP-003 polling to decide patch vs. full re-render.
458	   ---------------------------------------------------------- */
459	
460	/**
461	 * Extract a comparable state snapshot from API response objects.
462	 *
463	 * @param {object} project      - Response from API.getProject()
464	 * @param {Array|null} overviewResult - Response from API.getWorkPackageOverview() (may be null)
465	 * @returns {{
466	 *   status: string,
467	 *   last_updated: string,
468	 *   synthesis_generated: boolean,
469	 *   wpStatuses: Object.<string, { status: string, pipelineStages: Array }>,
470	 *   health: null | { work_packages_needing_reset: number }
471	 * }}
472	 */
473	function _snapshotProjectState(project, overviewResult) {
474	  var meta = (project && project.meta) || {};
475	  var wps  = (project && project.work_packages) || [];
476	
477	  // Build per-WP status map
478	  var wpStatuses = {};
479	  wps.forEach(function (wp) {
480	    if (!wp || !wp.work_package_id) return;
481	    wpStatuses[wp.work_package_id] = {
482	      status: wp.status || '',
483	      pipelineStages: [],
484	    };
485	  });
486	
487	  // Enrich with pipeline stage data from overview
488	  if (Array.isArray(overviewResult)) {
489	    overviewResult.forEach(function (entry) {
490	      if (!entry || !entry.work_package_id) return;
491	      var id = entry.work_package_id;
492	      var stages = Array.isArray(entry.pipeline_stages)
493	        ? entry.pipeline_stages.map(function (s) {
494	            return {
495	              type:         s.type        || '',
496	              status:       s.status      || '',
497	              agent:        s.agent       || '',
498	              rework_count: s.rework_count || 0,
499	            };
500	          })
501	        : [];
502	      if (wpStatuses[id]) {
503	        wpStatuses[id].pipelineStages = stages;
504	      } else {
505	        // Overview entry present without a matching WP in the main list.
506	        wpStatuses[id] = { status: '', pipelineStages: stages };
507	      }
508	    });
509	  }
510	
511	  return {
512	    status:               meta.status              || '',
513	    last_updated:         meta.last_updated         || '',
514	    synthesis_generated:  !!(project && project.synthesis_generated),
515	    wpStatuses:           wpStatuses,
516	    health:               null,  // populated asynchronously via getProjectHealth()
517	  };
518	}
519	
520	/**
521	 * Compare two project-state snapshots and classify the difference.
522	 *
523	 * Structural changes (require full re-render):
524	 *   - The number of work packages differs between snapshots.
525	 *   - The project transitioned to COMPLETE or ARCHIVED status.
526	 *
527	 * Data-only changes (patchable in-place):
528	 *   - Status badge changed but is not a structural transition.
529	 *   - Any per-WP status or pipeline-stage changed.
530	 *   - synthesis_generated flipped.
531	 *   - health changed (including null → value transitions).
532	 *   - last_updated changed.
533	 *
534	 * NOTE — per-WP iteration order: per-WP status/pipeline changes are detected by
535	 * iterating over `next.wpStatuses` keys only. A WP present in `prev` but absent
536	 * from `next` is therefore not tracked per-field; the structural `wpCount` check
537	 * handles that case before per-WP diffing is reached. In practice, a missing WP
538	 * always triggers a structural re-render, so the per-field gap is intentional.
539	 *
540	 * @param {object} prev - Previous snapshot from _snapshotProjectState().
541	 * @param {object} next - Current  snapshot from _snapshotProjectState().
542	 * @returns {{ type: 'none'|'data'|'structural', changes: object }}
543	 */
544	function _diffProjectState(prev, next) {
545	  var changes = {};
546	  var changeType = 'none';
547	
548	  function markData(key, from, to) {
549	    changes[key] = { from: from, to: to };
550	    if (changeType === 'none') changeType = 'data';

551	  }
552	
553	  function markStructural(key, from, to) {
554	    changes[key] = { from: from, to: to };
555	    changeType = 'structural';
556	  }
557	
558	  // ── WP count ────────────────────────────────────────────────────────
559	  var prevIds = Object.keys(prev.wpStatuses || {});
560	  var nextIds = Object.keys(next.wpStatuses || {});
561	  if (prevIds.length !== nextIds.length) {
562	    markStructural('wpCount', prevIds.length, nextIds.length);
563	  }
564	
565	  // ── Project status ──────────────────────────────────────────────────
566	  if (prev.status !== next.status) {
567	    var isStructuralStatus = next.status === 'COMPLETE' || next.status === 'ARCHIVED';
568	    if (isStructuralStatus) {
569	      markStructural('status', prev.status, next.status);
570	    } else {
571	      markData('status', prev.status, next.status);
572	    }
573	  }
574	
575	  // ── Per-WP statuses and pipeline stages ─────────────────────────────
576	  nextIds.forEach(function (id) {
577	    var prevWp = (prev.wpStatuses || {})[id] || { status: '', pipelineStages: [] };
578	    var nextWp = (next.wpStatuses || {})[id] || { status: '', pipelineStages: [] };
579	
580	    if (prevWp.status !== nextWp.status) {
581	      markData('wp.' + id + '.status', prevWp.status, nextWp.status);
582	    }
583	
584	    // Compare pipeline stages as JSON strings (simple deep-equal for flat objects)
585	    var prevStagesStr = JSON.stringify(prevWp.pipelineStages || []);
586	    var nextStagesStr = JSON.stringify(nextWp.pipelineStages || []);
587	    if (prevStagesStr !== nextStagesStr) {
588	      markData('wp.' + id + '.pipelineStages', prevWp.pipelineStages, nextWp.pipelineStages);
589	    }
590	  });
591	
592	  // ── synthesis_generated ─────────────────────────────────────────────
593	  if (!!prev.synthesis_generated !== !!next.synthesis_generated) {
594	    markData('synthesis_generated', prev.synthesis_generated, next.synthesis_generated);
595	  }
596	
597	  // ── health ──────────────────────────────────────────────────────────
598	  // null-to-value (or any value change) is data-only
599	  var prevHealthStr = JSON.stringify(prev.health || null);
600	  var nextHealthStr = JSON.stringify(next.health || null);
601	  if (prevHealthStr !== nextHealthStr) {
602	    markData('health', prev.health, next.health);
603	  }
604	
605	  // ── last_updated ────────────────────────────────────────────────────
606	  if (prev.last_updated !== next.last_updated) {
607	    markData('last_updated', prev.last_updated, next.last_updated);
608	  }
609	
610	  return { type: changeType, changes: changes };
611	}
