613	/* ----------------------------------------------------------
614	   4c-iv. Combined Poll Function
615	   Fetches project data and work-package overview each cycle,
616	   compares against the previous snapshot, and either patches
617	   the DOM in-place (data-only changes) or triggers a full
618	   re-render (structural changes).
619	
620	   Parameters:
621	     app           — root element passed to renderProjectDetail
622	     repo          — repository name
623	     slug          — project slug
624	     pollStateRef  — single-element array [snapshot] so the poll
625	                     function can read and write the last state
626	                     without a module-scoped variable
627	     pollController — the owning pollController object; used to
628	                     call stopPolling() before a structural
629	                     re-render so no competing interval remains
630	   ---------------------------------------------------------- */
631	/**
632	 * @param {Element}  app
633	 * @param {string}   repo
634	 * @param {string}   slug
635	 * @param {Array}    pollStateRef  — [lastSnapshot]; mutated in place
636	 * @param {object}   pollController
